namespace sv_d212e9467747492383a3ef27e925bffe.Services;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);
public record NotificationPrefs(bool EmailNotifications, bool PushNotifications, bool WeeklyDigest, List<string> MutedChannels);
public record SecuritySettings(bool TwoFactorEnabled, DateTime? LastPasswordChange, List<ActiveSession> Sessions);
public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);
public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

@namespace sv_d212e9467747492383a3ef27e925bffe.Components.Pages.Settings

<nav class="settings-sidebar" aria-label="Settings navigation">
    <ul class="nav nav-pills flex-column gap-1">
        @foreach (var section in _sections)
        {
            <li class="nav-item">
                <button type="button"
                        class="nav-link text-start w-100 @(ActiveSection == section.Key ? "active" : "")"
                        @onclick="() => OnSectionChanged.InvokeAsync(section.Key)"
                        aria-current="@(ActiveSection == section.Key ? "page" : null)">
                    <span class="me-2">@section.Icon</span>
                    @section.Label
                </button>
            </li>
        }
    </ul>
</nav>

@code {
    [Parameter, EditorRequired] public string ActiveSection { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback<string> OnSectionChanged { get; set; }

    private readonly record struct SectionInfo(string Key, string Label, string Icon);

    private static readonly SectionInfo[] _sections =
    [
        new("profile", "Profile", "👤"),
        new("notifications", "Notifications", "🔔"),
        new("security", "Security", "🔒"),
        new("appearance", "Appearance", "🎨"),
    ];
}

@namespace sv_d212e9467747492383a3ef27e925bffe.Components.Pages.Settings
@using sv_d212e9467747492383a3ef27e925bffe.Services

<div class="profile-section">
    <h4 class="mb-4">Profile Settings</h4>

    @if (_profile is null)
    {
        <p class="text-muted">Loading profile…</p>
        return;
    }

    <div class="row g-4">
        <div class="col-md-8">
            <div class="mb-3">
                <label class="form-label" for="displayName">Display Name</label>
                <input id="displayName" type="text" class="form-control"
                       @bind="_displayName" @bind:event="oninput" />
            </div>
            <div class="mb-3">
                <label class="form-label" for="email">Email</label>
                <input id="email" type="email" class="form-control"
                       @bind="_email" @bind:event="oninput" />
            </div>
            <div class="mb-3">
                <label class="form-label" for="bio">Bio</label>
                <textarea id="bio" class="form-control" rows="4"
                          @bind="_bio" @bind:event="oninput"></textarea>
            </div>
        </div>
        <div class="col-md-4">
            <div class="text-center">
                <div class="avatar-preview mb-2">
                    @if (!string.IsNullOrWhiteSpace(_avatarUrl))
                    {
                        <img src="@_avatarUrl" alt="Avatar" class="rounded-circle img-fluid" style="width:120px;height:120px;object-fit:cover;" />
                    }
                    else
                    {
                        <div class="rounded-circle bg-secondary d-flex align-items-center justify-content-center mx-auto"
                             style="width:120px;height:120px;">
                            <span class="text-white fs-1">👤</span>
                        </div>
                    }
                </div>
                <small class="text-muted text-break d-block">@(_avatarUrl ?? "No avatar set")</small>
            </div>
        </div>
    </div>

    <div class="d-flex gap-2 mt-3">
        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
            @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
            Save Changes
        </button>
        <button class="btn btn-outline-secondary" @onclick="Discard" disabled="@_saving">
            Discard Changes
        </button>
    </div>

    @if (_message is not null)
    {
        <div class="alert @(_isError ? "alert-danger" : "alert-success") mt-3 alert-dismissible fade show" role="alert">
            @_message
            <button type="button" class="btn-close" @onclick="() => _message = null"></button>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public UserProfile? Profile { get; set; }
    [Parameter, EditorRequired] public EventCallback<UserProfile> OnSave { get; set; }

    private UserProfile? _profile;
    private string _displayName = "";
    private string _email = "";
    private string _bio = "";
    private string _avatarUrl = "";
    private bool _saving;
    private string? _message;
    private bool _isError;

    protected override void OnParametersSet()
    {
        if (Profile != _profile)
        {
            _profile = Profile;
            ResetFields();
        }
    }

    private void ResetFields()
    {
        if (_profile is null) return;
        _displayName = _profile.DisplayName;
        _email = _profile.Email;
        _bio = _profile.Bio;
        _avatarUrl = _profile.AvatarUrl;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _message = null;
        try
        {
            var updated = new UserProfile(_displayName, _email, _avatarUrl, _bio);
            await OnSave.InvokeAsync(updated);
            _profile = updated;
            _message = "Profile saved successfully!";
            _isError = false;
        }
        catch
        {
            _message = "Failed to save profile. Please try again.";
            _isError = true;
        }
        finally
        {
            _saving = false;
        }
    }

    private void Discard()
    {
        ResetFields();
        _message = null;
    }
}

@namespace sv_d212e9467747492383a3ef27e925bffe.Components.Pages.Settings
@using sv_d212e9467747492383a3ef27e925bffe.Services

<div class="notifications-section">
    <h4 class="mb-4">Notification Preferences</h4>

    @if (Prefs is null)
    {
        <p class="text-muted">Loading preferences…</p>
        return;
    }

    <div class="mb-4">
        <div class="form-check form-switch mb-3">
            <input class="form-check-input" type="checkbox" id="emailNotif"
                   checked="@_emailNotifications"
                   @onchange="e => _emailNotifications = (bool)e.Value!" />
            <label class="form-check-label" for="emailNotif">
                <strong>Email Notifications</strong>
                <small class="d-block text-muted">Receive notifications via email</small>
            </label>
        </div>

        <div class="form-check form-switch mb-3">
            <input class="form-check-input" type="checkbox" id="pushNotif"
                   checked="@_pushNotifications"
                   @onchange="e => _pushNotifications = (bool)e.Value!" />
            <label class="form-check-label" for="pushNotif">
                <strong>Push Notifications</strong>
                <small class="d-block text-muted">Receive push notifications in your browser</small>
            </label>
        </div>

        <div class="form-check form-switch mb-3">
            <input class="form-check-input" type="checkbox" id="weeklyDigest"
                   checked="@_weeklyDigest"
                   @onchange="e => _weeklyDigest = (bool)e.Value!" />
            <label class="form-check-label" for="weeklyDigest">
                <strong>Weekly Digest</strong>
                <small class="d-block text-muted">Get a weekly summary of activity</small>
            </label>
        </div>
    </div>

    <h5 class="mb-3">Muted Channels</h5>
    <div class="mb-4">
        @foreach (var channel in AvailableChannels)
        {
            var isMuted = _mutedChannels.Contains(channel);
            <div class="form-check mb-2">
                <input class="form-check-input" type="checkbox" id="@($"ch-{channel}")"
                       checked="@isMuted"
                       @onchange="e => ToggleChannel(channel, (bool)e.Value!)" />
                <label class="form-check-label" for="@($"ch-{channel}")">@channel</label>
            </div>
        }
    </div>

    <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
        @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
        Save Preferences
    </button>

    @if (_message is not null)
    {
        <div class="alert alert-success mt-3 alert-dismissible fade show" role="alert">
            @_message
            <button type="button" class="btn-close" @onclick="() => _message = null"></button>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public NotificationPrefs? Prefs { get; set; }
    [Parameter, EditorRequired] public EventCallback<NotificationPrefs> OnSave { get; set; }
    [Parameter] public List<string> AvailableChannels { get; set; } = ["General", "Announcements", "Engineering", "Design", "Marketing", "Support"];

    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private HashSet<string> _mutedChannels = new();
    private bool _saving;
    private string? _message;
    private NotificationPrefs? _lastPrefs;

    protected override void OnParametersSet()
    {
        if (Prefs != _lastPrefs && Prefs is not null)
        {
            _lastPrefs = Prefs;
            _emailNotifications = Prefs.EmailNotifications;
            _pushNotifications = Prefs.PushNotifications;
            _weeklyDigest = Prefs.WeeklyDigest;
            _mutedChannels = new HashSet<string>(Prefs.MutedChannels);
        }
    }

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted)
            _mutedChannels.Add(channel);
        else
            _mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _message = null;
        try
        {
            var updated = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, _mutedChannels.ToList());
            await OnSave.InvokeAsync(updated);
            _lastPrefs = updated;
            _message = "Notification preferences saved!";
        }
        finally
        {
            _saving = false;
        }
    }
}

@namespace sv_d212e9467747492383a3ef27e925bffe.Components.Pages.Settings

<div class="card mb-4">
    <div class="card-header d-flex justify-content-between align-items-center"
         role="button" @onclick="() => _expanded = !_expanded"
         style="cursor:pointer;">
        <strong>Change Password</strong>
        <span>@(_expanded ? "▲" : "▼")</span>
    </div>
    @if (_expanded)
    {
        <div class="card-body">
            <div class="mb-3">
                <label class="form-label" for="currentPwd">Current Password</label>
                <input id="currentPwd" type="password" class="form-control"
                       @bind="_currentPassword" />
            </div>
            <div class="mb-3">
                <label class="form-label" for="newPwd">New Password</label>
                <input id="newPwd" type="password" class="form-control"
                       @bind="_newPassword" />
            </div>
            <div class="mb-3">
                <label class="form-label" for="confirmPwd">Confirm New Password</label>
                <input id="confirmPwd" type="password" class="form-control"
                       @bind="_confirmPassword" />
            </div>

            @if (_validationError is not null)
            {
                <div class="alert alert-warning py-2">@_validationError</div>
            }

            <button class="btn btn-warning" @onclick="SubmitAsync" disabled="@_saving">
                @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                Update Password
            </button>

            @if (_message is not null)
            {
                <div class="alert @(_isError ? "alert-danger" : "alert-success") mt-3 alert-dismissible fade show">
                    @_message
                    <button type="button" class="btn-close" @onclick="() => _message = null"></button>
                </div>
            }
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public EventCallback<(string Current, string New)> OnChangePassword { get; set; }

    private bool _expanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string? _validationError;
    private string? _message;
    private bool _isError;
    private bool _saving;

    private async Task SubmitAsync()
    {
        _validationError = null;
        _message = null;

        if (string.IsNullOrWhiteSpace(_currentPassword))
        {
            _validationError = "Current password is required.";
            return;
        }
        if (_newPassword.Length < 6)
        {
            _validationError = "New password must be at least 6 characters.";
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            _validationError = "New password and confirmation do not match.";
            return;
        }

        _saving = true;
        try
        {
