@namespace sv_d212e9467747492383a3ef27e925bffe.Components.Pages.Settings
@using sv_d212e9467747492383a3ef27e925bffe.Services

<div class="security-section">
    <h4 class="mb-4">Security Settings</h4>

    @if (Security is null)
    {
        <p class="text-muted">Loading security settings…</p>
        return;
    }

    <ChangePasswordPanel OnChangePassword="OnChangePassword" />

    <div class="card mb-4">
        <div class="card-body d-flex justify-content-between align-items-center">
            <div>
                <strong>Two-Factor Authentication</strong>
                <div class="mt-1">
                    @if (Security.TwoFactorEnabled)
                    {
                        <span class="badge bg-success">Enabled</span>
                    }
                    else
                    {
                        <span class="badge bg-secondary">Disabled</span>
                    }
                </div>
            </div>
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" id="twoFactor"
                       checked="@Security.TwoFactorEnabled" disabled
                       style="transform: scale(1.3);" />
            </div>
        </div>
        @if (Security.LastPasswordChange.HasValue)
        {
            <div class="card-footer text-muted small">
                Last password change: @Security.LastPasswordChange.Value.ToString("f")
            </div>
        }
    </div>

    <ActiveSessionsTable Sessions="Security.Sessions"
                         CurrentSessionId="@Security.Sessions.FirstOrDefault()?.Id"
                         OnRevoke="OnRevokeSession" />
</div>

@code {
    [Parameter, EditorRequired] public SecuritySettings? Security { get; set; }
    [Parameter, EditorRequired] public EventCallback<(string Current, string New)> OnChangePassword { get; set; }
    [Parameter, EditorRequired] public EventCallback<string> OnRevokeSession { get; set; }
}

@namespace sv_d212e9467747492383a3ef27e925bffe.Components.Pages.Settings
@using sv_d212e9467747492383a3ef27e925bffe.Services

<div class="appearance-section">
    <h4 class="mb-4">Appearance Settings</h4>

    @if (Settings is null)
    {
        <p class="text-muted">Loading appearance settings…</p>
        return;
    }

    <div class="row g-4">
        <div class="col-lg-7">
            <div class="mb-4">
                <h6>Theme</h6>
                @foreach (var theme in _themes)
                {
                    <div class="form-check form-check-inline">
                        <input class="form-check-input" type="radio" name="theme"
                               id="@($"theme-{theme.ToLower()}")"
                               checked="@(_theme == theme)"
                               @onchange="() => _theme = theme" />
                        <label class="form-check-label" for="@($"theme-{theme.ToLower()}")">@theme</label>
                    </div>
                }
            </div>

            <div class="mb-4">
                <h6>Font Size</h6>
                @foreach (var size in _fontSizes)
                {
                    <div class="form-check form-check-inline">
                        <input class="form-check-input" type="radio" name="fontSize"
                               id="@($"fs-{size.ToLower()}")"
                               checked="@(_fontSize == size)"
                               @onchange="() => _fontSize = size" />
                        <label class="form-check-label" for="@($"fs-{size.ToLower()}")">@size</label>
                    </div>
                }
            </div>

            <div class="mb-4">
                <h6>Language</h6>
                <select class="form-select" style="max-width:250px;"
                        @onchange="e => _language = e.Value!.ToString()!">
                    @foreach (var lang in _languages)
                    {
                        <option value="@lang.Key" selected="@(_language == lang.Key)">@lang.Value</option>
                    }
                </select>
            </div>

            <div class="mb-4">
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" id="compactMode"
                           checked="@_compactMode"
                           @onchange="e => _compactMode = (bool)e.Value!" />
                    <label class="form-check-label" for="compactMode">
                        <strong>Compact Mode</strong>
                        <small class="d-block text-muted">Reduce spacing and padding for denser content</small>
                    </label>
                </div>
            </div>

            <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
                @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                Save
            </button>

            @if (_message is not null)
            {
                <div class="alert alert-success mt-3 alert-dismissible fade show">
                    @_message
                    <button type="button" class="btn-close" @onclick="() => _message = null"></button>
                </div>
            }
        </div>

        <div class="col-lg-5">
            <h6>Live Preview</h6>
            <div class="border rounded p-3 @PreviewClasses" style="@PreviewStyles min-height:200px;">
                <h6 style="@PreviewFontStyle">Sample Heading</h6>
                <p style="@PreviewFontStyle" class="@(_compactMode ? "mb-1" : "mb-3")">
                    This is a preview of how your content will look with the selected appearance settings.
                </p>
                <div class="d-flex gap-2 @(_compactMode ? "mb-1" : "mb-3")">
                    <span class="badge bg-primary">Tag 1</span>
                    <span class="badge bg-secondary">Tag 2</span>
                    <span class="badge bg-success">Tag 3</span>
                </div>
                <button class="btn btn-sm btn-primary" style="@PreviewFontStyle" disabled>Sample Button</button>
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public AppearanceSettings? Settings { get; set; }
    [Parameter, EditorRequired] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string _theme = "System";
    private string _fontSize = "Medium";
    private string _language = "en";
    private bool _compactMode;
    private bool _saving;
    private string? _message;
    private AppearanceSettings? _lastSettings;

    private static readonly string[] _themes = ["Light", "Dark", "System"];
    private static readonly string[] _fontSizes = ["Small", "Medium", "Large"];
    private static readonly Dictionary<string, string> _languages = new()
    {
        ["en"] = "English",
        ["es"] = "Español",
        ["fr"] = "Français",
        ["de"] = "Deutsch",
        ["ja"] = "日本語",
        ["zh"] = "中文",
    };

    protected override void OnParametersSet()
    {
        if (Settings != _lastSettings && Settings is not null)
        {
            _lastSettings = Settings;
            _theme = Settings.Theme;
            _fontSize = Settings.FontSize;
            _language = Settings.Language;
            _compactMode = Settings.CompactMode;
        }
    }

    private string PreviewClasses
    {
        get
        {
            var effectiveTheme = _theme == "System" ? "Light" : _theme;
            return effectiveTheme == "Dark" ? "bg-dark text-white" : "bg-white text-dark";
        }
    }

    private string PreviewStyles
    {
        get
        {
            var effectiveTheme = _theme == "System" ? "Light" : _theme;
            return effectiveTheme == "Dark" ? "border-color: #495057 !important;" : "";
        }
    }

    private string PreviewFontStyle => _fontSize switch
    {
        "Small" => "font-size: 0.85rem;",
        "Large" => "font-size: 1.15rem;",
        _ => "font-size: 1rem;"
    };

    private async Task SaveAsync()
    {
        _saving = true;
        _message = null;
        try
        {
            var updated = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
            await OnSave.InvokeAsync(updated);
            _lastSettings = updated;
            _message = "Appearance settings saved!";
        }
        finally
        {
            _saving = false;
        }
    }
}

