+                        <label class="form-check-label" for="@($"fs-{size.ToLower()}")">@size</label>
+                    </div>
+                }
+            </div>
+
+            <div class="mb-4">
+                <h6>Language</h6>
+                <select class="form-select" style="max-width:250px;"
+                        @onchange="e => _language = e.Value!.ToString()!">
+                    @foreach (var lang in _languages)
+                    {
+                        <option value="@lang.Key" selected="@(_language == lang.Key)">@lang.Value</option>
+                    }
+                </select>
+            </div>
+
+            <div class="mb-4">
+                <div class="form-check form-switch">
+                    <input class="form-check-input" type="checkbox" id="compactMode"
+                           checked="@_compactMode"
+                           @onchange="e => _compactMode = (bool)e.Value!" />
+                    <label class="form-check-label" for="compactMode">
+                        <strong>Compact Mode</strong>
+                        <small class="d-block text-muted">Reduce spacing and padding for denser content</small>
+                    </label>
+                </div>
+            </div>
+
+            <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
+                @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
+                Save
+            </button>
+
+            @if (_message is not null)
+            {
+                <div class="alert alert-success mt-3 alert-dismissible fade show">
+                    @_message
+                    <button type="button" class="btn-close" @onclick="() => _message = null"></button>
+                </div>
+            }
+        </div>
+
+        <div class="col-lg-5">
+            <h6>Live Preview</h6>
+            <div class="border rounded p-3 @PreviewClasses" style="@PreviewStyles min-height:200px;">
+                <h6 style="@PreviewFontStyle">Sample Heading</h6>
+                <p style="@PreviewFontStyle" class="@(_compactMode ? "mb-1" : "mb-3")">
+                    This is a preview of how your content will look with the selected appearance settings.
+                </p>
+                <div class="d-flex gap-2 @(_compactMode ? "mb-1" : "mb-3")">
+                    <span class="badge bg-primary">Tag 1</span>
+                    <span class="badge bg-secondary">Tag 2</span>
