+    [Parameter, EditorRequired] public AppearanceSettings? Settings { get; set; }
+    [Parameter, EditorRequired] public EventCallback<AppearanceSettings> OnSave { get; set; }
+
+    private string _theme = "System";
+    private string _fontSize = "Medium";
+    private string _language = "en";
+    private bool _compactMode;
+    private bool _saving;
+    private string? _message;
+    private AppearanceSettings? _lastSettings;
+
+    private static readonly string[] _themes = ["Light", "Dark", "System"];
+    private static readonly string[] _fontSizes = ["Small", "Medium", "Large"];
+    private static readonly Dictionary<string, string> _languages = new()
+    {
+        ["en"] = "English",
+        ["es"] = "Español",
+        ["fr"] = "Français",
+        ["de"] = "Deutsch",
+        ["ja"] = "日本語",
+        ["zh"] = "中文",
+    };
+
+    protected override void OnParametersSet()
+    {
+        if (Settings != _lastSettings && Settings is not null)
+        {
+            _lastSettings = Settings;
+            _theme = Settings.Theme;
+            _fontSize = Settings.FontSize;
+            _language = Settings.Language;
+            _compactMode = Settings.CompactMode;
+        }
+    }
+
+    private string PreviewClasses
+    {
+        get
+        {
+            var effectiveTheme = _theme == "System" ? "Light" : _theme;
+            return effectiveTheme == "Dark" ? "bg-dark text-white" : "bg-white text-dark";
+        }
+    }
+
+    private string PreviewStyles
+    {
+        get
+        {
+            var effectiveTheme = _theme == "System" ? "Light" : _theme;
+            return effectiveTheme == "Dark" ? "border-color: #495057 !important;" : "";
+        }
+    }
+
+    private string PreviewFontStyle => _fontSize switch
+    {
+        "Small" => "font-size: 0.85rem;",
+        "Large" => "font-size: 1.15rem;",
+        _ => "font-size: 1rem;"
+    };
+
+    private async Task SaveAsync()
+    {
+        _saving = true;
+        _message = null;
+        try
+        {
+            var updated = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
+            await OnSave.InvokeAsync(updated);
+            _lastSettings = updated;
+            _message = "Appearance settings saved!";
+        }
+        finally
+        {
+            _saving = false;
+        }
+    }
+}
+

