toolArgs.file_text:
.settings-dashboard {
    display: flex;
    gap: 2rem;
    min-height: 70vh;
}

.settings-sidebar {
    min-width: 200px;
    max-width: 220px;
    flex-shrink: 0;
}

::deep .settings-sidebar .nav-link {
    border-radius: 0.5rem;
    color: #495057;
    font-weight: 500;
    padding: 0.65rem 1rem;
    transition: background-color 0.15s, color 0.15s;
}

::deep .settings-sidebar .nav-link:hover:not(.active) {
    background-color: #f0f0f0;
}

::deep .settings-sidebar .nav-link.active {
    background-color: #0d6efd;
    color: #fff;
}

.settings-content {
    flex: 1;
    min-width: 0;
}

@media (max-width: 768px) {
    .settings-dashboard {
        flex-direction: column;
        gap: 1rem;
    }

    .settings-sidebar {
        max-width: none;
    }

    ::deep .settings-sidebar .nav {
        flex-direction: row !important;
        flex-wrap: wrap;
        gap: 0.25rem !important;
    }

    ::deep .settings-sidebar .nav-link {
        padding: 0.4rem 0.75rem;
        font-size: 0.9rem;
    }
}

